/* prog56_kruskal_mst.c
 * Re‑implementation of the original (obfuscated) program.
 * Behaviour:
 *   prog56_kruskal_mst N
 *   reads up to 9 edges (u v w) from stdin,
 *   builds a minimum spanning tree with Kruskal,
 *   prints either the total weight and the edges of the MST
 *   or "DISCONNECTED".
 * The original program only supports up to 6 vertices and 9 edges.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_VERTICES 6
#define MAX_EDGES    9

/* ---------- union‑find (disjoint set) ---------- */
static int parent[MAX_VERTICES];

static void uf_init(int n)
{
    for (int i = 0; i < n; ++i)
        parent[i] = i;
}

/* find with path compression */
static int uf_find(int x)
{
    if (parent[x] != x)
        parent[x] = uf_find(parent[x]);
    return parent[x];
}

/* union – returns 1 if a merge happened, 0 otherwise */
static int uf_union(int a, int b)
{
    int ra = uf_find(a);
    int rb = uf_find(b);
    if (ra == rb)
        return 0;
    parent[ra] = rb;
    return 1;
}

/* ---------- edge handling ---------- */
typedef struct {
    int u, v, w;
} Edge;

static int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    return (ea->w > eb->w) - (ea->w < eb->w);   /* ascending by weight */
}

int main(int argc, char **argv)
{
    /* ----- argument handling ----- */
    if (argc != 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    errno = 0;
    long n_long = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0' || n_long <= 0 || n_long > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;               /* number of vertices */

    /* ----- read edges ----- */
    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES) {
        int u, v, w;
        int rc = scanf("%d %d %d", &u, &v, &w);
        if (rc == EOF || rc < 3)
            break;                     /* stop on EOF or malformed line */
        edges[edge_cnt].u = u;
        edges[edge_cnt].v = v;
        edges[edge_cnt].w = w;
        ++edge_cnt;
    }

    /* ----- Kruskal ----- */
    qsort(edges, edge_cnt, sizeof(Edge), cmp_edge);

    uf_init(n);

    int sel_u[MAX_VERTICES - 1];
    int sel_v[MAX_VERTICES - 1];
    int sel_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && sel_cnt < n - 1; ++i) {
        int u = edges[i].u;
        int v = edges[i].v;
        /* ignore edges that refer to vertices outside the range [0,n) */
        if (u < 0 || u >= n || v < 0 || v >= n)
            continue;
        if (uf_union(u, v)) {
            sel_u[sel_cnt] = u;
            sel_v[sel_cnt] = v;
            total_weight += edges[i].w;
            ++sel_cnt;
        }
    }

    /* ----- output ----- */
    if (sel_cnt == n - 1) {
        printf("weight=%d edges=", total_weight);
        for (int i = 0; i < sel_cnt; ++i) {
            printf("%d-%d", sel_u[i], sel_v[i]);
        }
        putchar('\n');
    } else {
        puts("DISCONNECTED");
    }

    return 0;
}
